-- Loads and checks data/post_quest_items.lua (generated by tools/build_post_quest.py):
-- quest items still used after their quest ("keep") and quest-only items that are no
-- longer needed once their quests are finished ("done").
--
-- Pure apart from the require in load(). Owns nothing.

local PostQuestData = {}

PostQuestData.SCHEMA = 1

local function isId(value)
    return math.type(value) == "integer" and value >= 0
end

-- { [itemId] = { questId, ... } } -> { [itemId] = { quest, ... } }, dropping any entry
-- with a bad id or a quest the file doesn't describe.
local function checkItems(raw, quests)
    local items = {}

    if type(raw) ~= "table" then
        return items
    end

    for itemId, questIds in pairs(raw) do
        if isId(itemId) and type(questIds) == "table" and #questIds > 0 then
            local list = {}

            for _, questId in ipairs(questIds) do
                if not quests[questId] then
                    list = nil
                    break
                end

                list[#list + 1] = quests[questId]
            end

            if list then
                items[itemId] = list
            end
        end
    end

    return items
end

-- { [itemId] = { achievementId, ... } }; a broken entry is dropped, which keeps that
-- item for good (the safe side).
local function checkUntil(raw)
    local result = {}

    if type(raw) ~= "table" then
        return result
    end

    for itemId, ids in pairs(raw) do
        if isId(itemId) and type(ids) == "table" and #ids > 0 then
            local valid = true

            for _, achievementId in ipairs(ids) do
                valid = valid and isId(achievementId)
            end

            if valid then
                result[itemId] = ids
            end
        end
    end

    return result
end

-- Returns { status = "ok", quests, achievements, keep, keepUntil, done } or
-- { status = "incompatible", message }. quests[questId] = { id, name, category };
-- achievements[id] = name; keep/done[itemId] = list of those quests;
-- keepUntil[itemId] = achievement ids that end a keep item's use.
function PostQuestData.build(raw)
    if type(raw) ~= "table" then
        return { status = "incompatible", message = "The post-quest data file didn't load." }
    end

    if raw.schema ~= PostQuestData.SCHEMA then
        return {
            status = "incompatible",
            message = "Post-quest data schema " .. tostring(raw.schema) .. " isn't supported (expected "
                .. PostQuestData.SCHEMA .. ").",
        }
    end

    if type(raw.quests) ~= "table" then
        return { status = "incompatible", message = "The post-quest data file is missing its quests." }
    end

    local quests = {}

    for questId, quest in pairs(raw.quests) do
        if isId(questId) and type(quest) == "table" and type(quest.name) == "string"
            and type(quest.category) == "string" then
            quests[questId] = { id = questId, name = quest.name, category = quest.category }
        end
    end

    -- Names are only tooltip text: a bad entry is dropped and the tooltip falls back.
    local achievements = {}

    if type(raw.achievements) == "table" then
        for achievementId, name in pairs(raw.achievements) do
            if isId(achievementId) and type(name) == "string" and name ~= "" then
                achievements[achievementId] = name
            end
        end
    end

    return {
        status = "ok",
        quests = quests,
        achievements = achievements,
        keep = checkItems(raw.keep, quests),
        keepUntil = checkUntil(raw.keepUntil),
        done = checkItems(raw.done, quests),
    }
end

-- A file that throws while loading counts as incompatible: the other markers still work.
function PostQuestData.load()
    local ok, raw = pcall(function()
        return require("data/post_quest_items")
    end)

    if not ok then
        return { status = "incompatible", message = "The post-quest data file failed to load: " .. tostring(raw) }
    end

    return PostQuestData.build(raw)
end

return PostQuestData
